    ('200010', '200', 'Fornecimento dos medicamentos registrados na Anvisa, quando adquiridos por órgãos da administração pública direta, autarquias, fundações públicas e entidades imunes, observado o art. 146 da Lei Complementar nº 214, de 2025.', 'Fornecimento dos medicamentos registrados na Anvisa, adquiridos por órgãos da administração pública', 0, 0, 100.0000, 100.0000, 2, 1, 1, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art146', '2026-06-22', '2025-05-05', NULL),
